class IdempotentHandler:
    def __init__(self):
        self.count = 0
        self.store = {}

    def handle(self, key, payload):
        if key in self.store:
            saved_payload, body = self.store[key]
            if saved_payload != payload:
                return 422, {'error': 'key reused with different payload'}
            return 201, body
        self.count += 1
        body = {'id': self.count, 'amount': payload['amount']}
        self.store[key] = (dict(payload), body)
        return 201, body

