def rate_limit(times, limit, window):
    allowed_times = []
    result = []
    for t in times:
        recent = [a for a in allowed_times if a > t - window]
        if len(recent) < limit:
            allowed_times.append(t)
            result.append(True)
        else:
            result.append(False)
    return result
